#!/usr/bin/env dotnet
#:sdk Microsoft.NET.Sdk.Web #:package MagicOnion@5.0.0 #:package MQTTnet@4.1.5 #:package System.Threading.Channels@8.0.0 #:package Microsoft.Extensions.Caching.StackExchangeRedis@8.0.0 #:property LangVersion=preview #:property TargetFramework=net11.0 #:property Nullable=enable #:property ImplicitUsings=enable  using MagicOnion; using MQTTnet; using MQTTnet.Client; using System.Threading.Channels; using Microsoft.Extensions.Caching.Distributed;  var builder = WebApplication.CreateBuilder();  // 1. MQTT集群配置 builder.Services.AddSingleton<IMqttClient>(sp =>  {     var factory = new MqttFactory();     var client = factory.CreateMqttClient();     var options = new MqttClientOptionsBuilder()         .WithTcpServer("cluster-node1", 1883)         .WithTcpServer("cluster-node2", 1883)         .WithCleanSession(false) // 保持会话状态         .WithSessionExpiryInterval(3600) // 1小时会话过期         .Build();     client.ConnectAsync(options).Wait();     return client; });  // 2. QoS控制处理器 builder.Services.AddSingleton<IQosController>(sp =>      new ChannelQosController(         Channel.CreateBounded<QosMessage>(10000),         new ThreadLocal<Span<byte>>(() => stackalloc byte[128])));  // 3. 消息持久化存储 builder.Services.AddStackExchangeRedisCache(options =>  {     options.Configuration = "localhost:6379";     options.InstanceName = "MQTT_"; });  // 4. 零拷贝消息处理器 builder.Services.AddSingleton<IMqttProcessor>(sp =>      new EnhancedMqttProcessor(         Channel.CreateBounded<MqttMessage>(10000),         sp.GetRequiredService<IDistributedCache>(),         new ThreadLocal<Span<byte>>(() => stackalloc byte[1024])));  var app = builder.Build(); app.MapGet("/", () => "Enhanced MQTT Ready"); app.Run();  // QoS控制器 [SkipLocalsInit] public class ChannelQosController {     [MethodImpl(MethodImplOptions.AggressiveOptimization)]     public unsafe void HandleQos(QosMessage message)     {         Span<byte> buffer = stackalloc byte[128];         fixed (byte* ptr = buffer)         {             if ((long)ptr % 64 == 0)             {                 // SIMD优化处理QoS逻辑             }         }     } }  // 增强版MQTT处理器 [SkipLocalsInit] public class EnhancedMqttProcessor : IMqttProcessor {     [MethodImpl(MethodImplOptions.AggressiveOptimization)]     public unsafe void ProcessWithPersistence(MqttMessage message)     {         Span<byte> buffer = stackalloc byte[1024];         fixed (byte* ptr = buffer)         {             if ((long)ptr % 64 == 0)             {                 // 持久化处理逻辑             }         }     } }  [MessagePackObject] public class QosMessage {     [Key(0)]     public MqttQualityOfServiceLevel Level { get; set; }          [Key(1)]     public ulong MessageId { get; set; }          [Key(2)]     public DateTimeOffset Timestamp { get; set; } }
